import 'dart:convert'; import 'dart:io'; import 'package:http/http.dart' as http; import 'package:shared_preferences/shared_preferences.dart';
class ApiException implements Exception{final String message;ApiException(this.message);@override String toString()=>message;}
class TechnicianApi{TechnicianApi({String? baseUrl}):baseUrl=baseUrl??const String.fromEnvironment('API_URL',defaultValue:'http://10.0.2.2:4000/api');final String baseUrl;String? token;
Future<void> restore()async=>token=(await SharedPreferences.getInstance()).getString('technician_token');Future<void> login(String email,String password)async{final d=await _send('POST','/auth/login',body:{'email':email,'password':password,'portal':'technician'});token=d['token'];await(await SharedPreferences.getInstance()).setString('technician_token',token!);}Future<void>logout()async{token=null;await(await SharedPreferences.getInstance()).remove('technician_token');}
Future<List<dynamic>>jobs()=>_send('GET','/jobs').then((v)=>v['data']);Future<Map<String,dynamic>>updateJob(String id,String status,{Map<String,dynamic>? extra})=>_send('PATCH','/jobs/$id/status',body:{'status':status,...?extra});Future<Map<String,dynamic>>upload(File file,String kind,String jobId)async{final q=http.MultipartRequest('POST',Uri.parse('$baseUrl/uploads'));q.headers['Authorization']='Bearer $token';q.fields.addAll({'kind':kind,'jobId':jobId});q.files.add(await http.MultipartFile.fromPath('file',file.path));return _decode(await http.Response.fromStream(await q.send()));}
Future<Map<String,dynamic>>_send(String method,String path,{Map<String,dynamic>?body})async{final u=Uri.parse('$baseUrl$path'),h={'Content-Type':'application/json',if(token!=null)'Authorization':'Bearer $token'};try{late http.Response r;if(method=='GET')r=await http.get(u,headers:h);else if(method=='PATCH')r=await http.patch(u,headers:h,body:jsonEncode(body));else r=await http.post(u,headers:h,body:jsonEncode(body));return _decode(r);}on SocketException{throw ApiException('Cannot connect to SignFix. Check your network.');}}Map<String,dynamic>_decode(http.Response r){final d=jsonDecode(r.body)as Map<String,dynamic>;if(r.statusCode<200||r.statusCode>=300)throw ApiException(d['error']??'Request failed');return d;}}
